oi criado com sucesso.','Unable to create backup this time.'=>'Não foi possível criar o backup desta vez.','Action not allowed.'=>'Ação não permitida.','Cleanup of %s data failed.'=>'Falha na limpeza dos dados %s.','Cleanup of %s data successfully done.'=>'A limpeza dos dados %s foi concluída com sucesso.','Insert Link in Content'=>'Inserir ligação no conteúdo','Copy Link URL to Clipboard'=>'Copiar o URL do ligação para a área de transferência','The canonical URL you entered does not seem to be a valid URL. Please double check it in the SEO meta box &raquo; Advanced tab.'=>'A URL canônica que você inseriu não parece ser válida. Verifique-a novamente na caixa de meta de SEO, na guia “Avançado”.','Thank you for using <a href="%s" target="_blank">Rank Math</a>'=>'Obrigado por usar <a href="%s" target="_blank">o Rank Math</a>','Import &amp; Export'=>'Importação e exportação','Setup Wizard'=>'Assistente de configuração','Facebook profile URL'=>'URL do perfil do Facebook','Twitter username (without @)'=>'Nome de utilizador do Twitter (sem @)','Link Title'=>'Título do ligação','Add <code>rel="nofollow"</code>'=>'Adicionar <code>rel=&quot;nofollow&quot;</code>','Add Link'=>'Adicionar ligação','Insert/edit link'=>'Inserir/editar ligação','Help &amp; Support'=>'Ajuda &amp; suporte']];